import{_ as s,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"材料与能源","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/index.md","filePath":"topics/materials/index.md"}'),i={name:"topics/materials/index.md"};function a(o,t,g,c,l,h){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="材料与能源" tabindex="-1">材料与能源 <a class="header-anchor" href="#材料与能源" aria-label="Permalink to &quot;材料与能源&quot;">​</a></h1><blockquote><p>超导、电池、热控——材料科学的前沿突破</p></blockquote><h2 id="文件列表" tabindex="-1">文件列表 <a class="header-anchor" href="#文件列表" aria-label="Permalink to &quot;文件列表&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-25-materials.html">科学日报 2026-10-25（材料/柔性钙钛矿组件）</a> — 第44期科学板块：<strong>把「SAM 锚定」与「钙钛矿结晶」解耦</strong>——柔性基底表面羟基脱附会破坏自组装单分子层（SAM）锚定并扰乱结晶；用<strong>解耦的 SAM–钙钛矿共沉积</strong>（降低 SAM–钙钛矿相互作用以加速锚定、同时改善结晶）：<strong>750 cm² 组件认证 20.2%</strong>（PEAI 钝化）、<strong>14.55 cm² 达 22.0%</strong>（DAPDI 钝化）、<strong>85°C/65%RH 最大功率点跟踪 1044 h 仅衰减 8%</strong>，并通过柔性便携 PSM 国际商业化评估标准全序列 → <strong>当两个必要过程共享同一耦合通道而互相拖累时，先拆耦合，比分别调参更根本</strong>（Science, 10.1126/science.aef9745）｜亦见 <code>topics/physics/index.md</code></li><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-23-materials.html">科学日报 2026-10-23（材料/自旋电子学/多相催化）</a> — 第42期科学板块两篇：①<strong>全反铁磁隧道结 PtMn₃|MgO|PtMn₃</strong> 室温 <strong>TMR 363%</strong>，并以 <strong>~10 MA cm⁻²</strong> 首次实现<strong>电流驱动的翻转</strong>，命名为「<strong>八极矩驱动的自旋转移矩（OTT）</strong>」（源于<strong>内/间子晶格自旋流不平衡</strong> ≡ 每层非零的<strong>净团簇八极矩极化</strong>）→ 反铁磁自旋电子学新材料平台（Nature, 10.1038/s41586-026-11172-5）；②<strong>FER 分子筛空间限域 + 高 CO/烯烃比(360)</strong> 把烯烃羰基化主产物从<strong>叔羧酸</strong>改为<strong>伯/仲羧酸</strong>：<strong>丙酸 80% 选择性/100 h</strong>、<strong>异丁酸 95% 选择性/750 h</strong>；活性位分别为 <strong>8-MR 的 T2–O5</strong>（乙烯）与 <strong>10-MR 的 T3–O1</strong>（丙烯）→ <strong>几何即功能、同框架两套可分别寻址的位点</strong>（Nature, 10.1038/s41586-026-11183-2）｜①亦见 <code>topics/quantum-physics/index.md</code></li><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-22-materials.html">科学日报 2026-10-22（材料/生物催化）</a> — 第41期科学板块两篇：①<strong>把酶热嵌入可堆肥聚酯</strong>（PBS/PBSA/PCL/PBAT）——<strong>757 m 深海 5 个月近完全降解</strong>、<strong>5,503 m</strong> 仍有中等降解、近岸仅 <strong>0.1 wt%</strong> 痕量酶即见效，力学性能不变（BOD 支持矿化；Nature, 10.1038/s41586-026-11192-1）；②<strong>从头设计人工金属酶光催化剂</strong>——生成式蛋白设计造骨架 + 定向进化调<strong>对映选择性</strong>，蛋白环境<strong>延长激发态寿命、组织底物</strong>，可直接用市售外消旋配合物（Nature, 10.1038/s41586-026-11317-6）</li><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-21-materials.html">科学日报 2026-10-21（材料/凝聚态）</a> — 第40期科学板块两篇：①极简氨基酸自组装出<strong>螺旋位错诱导的层级结晶「超螺旋」</strong>（旋性/几何可由对映体过量编程），<strong>压电响应相对随机聚集体放大 17 倍</strong> → 高增益方向选择性运动传感（PNAS, 10.1073/pnas.2611417123）；②近 0° 扭转 <strong>WSe₂/WS₂ 莫尔超晶格</strong>中<strong>栅压可调的手性自旋模式（CSM）</strong>：填充可驱动「手性自旋激子↔激子极化子」转变、塞曼效应确认自旋翻转、单位填充现电荷转移绝缘体（Science, 10.1126/science.adq6530）｜②亦见 <code>topics/quantum-physics/index.md</code></li><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-11.html">科学日报 2026-10-11：借氧气活化的不对称酶促氢膦酰化</a> — 改造黄素依赖酶经 O₂ 活化产生&quot;磷中心自由基&quot;，实现高对映选择性的酶促 C–P 成键，可编程合成含磷药物/农化骨架（Science, 10.1126/science.aef3001）</li><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-08.html">科学日报 2026-10-08：7 eV 超宽带隙半导体</a> — 硅掺杂 α-(AlₓGa₁₋ₓ)₂O₃，带隙 &gt;7.0 eV 超立方氮化硼，室温电导率高 1 亿倍（Nature, 10.1038/s41586-026-11085-3）</li><li><a href="/zhishiku-reading/topics/materials/science-daily-2026-10-09.html">科学日报 2026-10-09：挥发性共晶调控钙钛矿结晶</a> — ZnBr₂/MACl 共晶，晶界局部熔融降低缺陷；电池 26.5%（认证 25.9%）、&gt;15 cm² 组件 23.9%、85°C/1400h 保持 85.8%、LED EQE 26.1%（Science, 10.1126/science.aeb4554）</li><li><a href="/zhishiku-reading/topics/materials/2026-q3-breakthroughs.html">2026 Q3 突破</a> — 超导（纳米雕刻/AI发现）、电池（钠离子）、热控（可编程材料）、人工光合作用</li></ul>',4)])])}const u=s(i,[["render",a]]);export{m as __pageData,u as default};
